def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip().lower()

        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1).strip()

        if value.count("@") == 1:
            local, domain = value.split("@")
            if domain in {"gmail.com", "googlemail.com"}:
                local = local.split("+", 1)[0].replace(".", "")
                value = local + "@gmail.com"

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if (
            not local
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return value

    def normalize_phone(value):
        value = re.split(r"ext|x|#", value, maxsplit=1, flags=re.IGNORECASE)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()
        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", value):
            value = "0" + value
        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value.strip(), fmt)
            except ValueError:
                pass
        raise ValueError("Invalid updated value: {!r}".format(value))

    def normalize_tags(value):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value)
            if tag.strip()
        }

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    records = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        # Rows without either usable contact method are excluded entirely.
        if not email and not phone:
            continue

        records.append({
            "input_index": input_index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "zip": normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": row["source"].strip().lower(),
            "tags": normalize_tags(row["tags"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "updated_dt": parse_updated(row["updated"]),
        })

    parent = list(range(len(records)))
    rank = [0] * len(records)

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        root_a = find(a)
        root_b = find(b)

        if root_a == root_b:
            return

        if rank[root_a] < rank[root_b]:
            root_a, root_b = root_b, root_a

        parent[root_b] = root_a
        if rank[root_a] == rank[root_b]:
            rank[root_a] += 1

    by_email = {}
    by_phone_and_last_name = {}

    for i, record in enumerate(records):
        if record["email"]:
            previous = by_email.get(record["email"])
            if previous is None:
                by_email[record["email"]] = i
            else:
                union(i, previous)

        if record["phone"] and record["last_name"]:
            key = (record["phone"], record["last_name"].casefold())
            previous = by_phone_and_last_name.get(key)
            if previous is None:
                by_phone_and_last_name[key] = i
            else:
                union(i, previous)

    groups = {}
    for i, record in enumerate(records):
        groups.setdefault(find(i), []).append(record)

    def choose(group, field):
        candidates = [record for record in group if record[field]]
        if not candidates:
            return ""

        chosen = max(
            candidates,
            key=lambda record: (
                record["source"].casefold() == "manual",
                record["updated_dt"],
                -record["input_index"],
            ),
        )
        return chosen[field]

    output = []

    for group in sorted(
        groups.values(),
        key=lambda group: min(record["input_index"] for record in group),
    ):
        all_tags = set()
        for record in group:
            all_tags.update(record["tags"])

        latest_updated = max(record["updated_dt"] for record in group)

        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": (
                "Y" if any(record["opted_out"] for record in group) else "N"
            ),
            "updated": latest_updated.date().isoformat(),
        })

    return output
